bash -lc "python3 - << 'PY'
path = '/src/libxml2/dict.c'
import io,sys
text = open(path,'r',encoding='utf-8').read()
old = '''for (i = 0; i < maxLen && data[i]; i++) {
        HASH_UPDATE(h1, h2, data[i]);
    }'''
new = '''size_t maxProcess = maxLen;
    if (maxLen == SIZE_MAX)
        maxProcess = 256;
    for (i = 0; i < maxProcess && data[i]; i++) {
        HASH_UPDATE(h1, h2, data[i]);
    }'''
if old in text:
    text = text.replace(old, new)
    open(path,'w',encoding='utf-8').write(text)
    print('patched')
else:
    print('pattern not found, patch aborted')
    sys.exit(1)
PY"

bash -lc "sed -i '/HASH_INIT(h1, h2, seed);/a
	if (maxLen == SIZE_MAX) {
		maxLen = 256;
	}
' /src/libxml2/dict.c"

bash -lc 'cd /src/libxml2 && sed -i "/HASH_INIT(h1, h2, seed);/a\n	if (maxLen == SIZE_MAX) {
		maxLen = 256;
	}
" dict.c'

bash -lc '
set -e
# Remove old broken function block for xmlDictHashName
awk \'/^static unsigned[[:space:]]+xmlDictHashName\(/ {in_func=1; depth=0; next}
in_func {
  if (index($0,"{")>0) depth++;
  if (index($0,"}")>0) depth--;
  if (depth==0) { in_func=0; next }
  next
}
{ print }\' /src/libxml2/dict.c > /tmp/dict.c.rem && mv /tmp/dict.c.rem /src/libxml2/dict.c

# Insert new function before the next ATTRIBUTE_NO_SANITIZE_INTEGER occurrence
awk '
BEGIN{ins=0}
/^[[:space:]]*ATTRIBUTE_NO_SANITIZE_INTEGER/ && !ins {
  print "static unsigned";
  print "xmlDictHashName(unsigned seed, const xmlChar* data, size_t maxLen,";
  print "                size_t *plen) {";
  print "    unsigned h1, h2;";
  print "    size_t i;";
  print "";
  print "    HASH_INIT(h1, h2, seed);";
  print "";
  print "    size_t maxProcess = maxLen;";
  print "    if (maxLen == SIZE_MAX) {";
  print "        maxProcess = 256;";
  print "    }";
  print "    for (i = 0; i < maxProcess && data[i]; i++) {";
  print "        HASH_UPDATE(h1, h2, data[i]);";
  print "    }";
  print "";
  print "    HASH_FINISH(h1, h2);";
  print "";
  print "    *plen = i;";
  print "    return(h2 | MAX_HASH_SIZE);";
  print "}";
  ins=1;
}
{ print }' /src/libxml2/dict.c > /tmp/dict.c.new && mv /tmp/dict.c.new /src/libxml2/dict.c
'

bash -lc 'perl -0777 -pe 's/HASH_INIT\(h1, h2, seed\);/$&\n
    size_t maxProcess = maxLen;
    if (maxLen == SIZE_MAX) {
        maxProcess = 256;
    }

    for (i = 0; i < maxProcess && data[i]; i++) {\n        HASH_UPDATE(h1, h2, data[i]);\n    }/s' -i /src/libxml2/dict.c'

bash -lc 'python3 - <<"PY"
path = "/src/libxml2/dict.c"
text = open(path, "r", encoding="utf-8").read()
anchor = "HASH_INIT(h1, h2, seed);"
pos = text.find(anchor)
if pos == -1:
    print("anchor not found")
    import sys; sys.exit(1)
insert_pos = pos + len(anchor)
patch = "
    if (maxLen == SIZE_MAX) { maxLen = strlen((const xmlChar*)data); }
    for (i = 0; i < maxLen && data[i]; i++) {
        HASH_UPDATE(h1, h2, data[i]);
    }
"
new_text = text[:insert_pos] + patch + text[insert_pos:]
open(path, 'w', encoding='utf-8').write(new_text)
print("patched")
PY'

